int function(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        byte b = bb.get(i++);
        if ((b & 0x80) == 0) {
            // Single-byte character
            sb.append((char) b);
        } else if ((b & 0xE0) == 0xC0) {
            // Two-byte character
            if (bb.remaining() < 1) break;
            char ch = (char) ((b & 0x1F) << 6);
            b = bb.get(i++);
            ch |= (b & 0x3F);
            sb.append(ch);
        } else if ((b & 0xF0) == 0xE0) {
            // Three-byte character
            if (bb.remaining() < 2) break;
            char ch = (char) ((b & 0x0F) << 12);
            b = bb.get(i++);
            ch |= (char) ((b & 0x3F) << 6);
            b = bb.get(i++);
            ch |= (b & 0x3F);
            sb.append(ch);
        } else if ((b & 0xF8) == 0xF0) {
            // Four-byte character
