void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Graph and resultMap cannot be null");
    }

    Set<V> leftPartition = new HashSet<>();
    Set<V> rightPartition = new HashSet<>(resultMap.values());

    // Split the vertices into two partitions
    // Assuming an even split for demonstration, adjust as necessary
    int size = rightPartition.size();
    Iterator<V> iterator = rightPartition.iterator();
    for (int i = 0; i < size / 2 && iterator.hasNext(); i++) {
        leftPartition.add(iterator.next());
        iterator.remove();
    }

    // Add vertices to the graph
    for (V vertex : leftPartition) {
        target.addVertex(vertex);
    }
    for (V vertex : rightPartition) {
        target.addVertex(vertex);
    }

    // Connect every vertex in the left partition to every vertex in the right partition
    for (V leftVertex : leftPartition) {
        for (V rightVertex : rightPartition) {
            target.addEdge(leftVertex, rightVertex);
        }
    }
}

