Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType parameterizedType = (ParameterizedType) genericType;
    Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
    TypeVariable<?>[] typeVariables = targetType.getTypeParameters();

    if (actualTypeArguments.length != typeVariables.length) {
        return null;
    }

    Map<TypeVariable<?>, Class<?>> typeArgumentMappings = new HashMap<>();
    for (int i = 0; i < typeVariables.length; i++) {
        typeArgumentMappings.put(typeVariables[i], (Class<?>) actualTypeArguments[i]);
    }

    Class<?>[] resolvedArguments = new Class<?>[actualTypeArguments.length];
    for (int i = 0; i < actualTypeArguments.length; i++) {
        if (actualTypeArguments[i] instanceof TypeVariable) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) actualTypeArguments[i];
            if (typeArgumentMappings.containsKey(typeVariable)) {
                resolvedArguments[i] = typeArgumentMappings.get(typeVariable);
            } else {
                return null;
            }
        } else if (actualTypeArguments[i] instanceof Class) {
            resolvedArguments[i] = (Class<?>) actualTypeArguments[i];
        } else {
            return null;
        }
    }

    return resolvedArguments;
}

