private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, so we need to pop argument types
        int i = 1;
        while (descriptor.charAt(i) != ')') {
            i = popType(descriptor, i);
        }
    } else {
        // It's a type descriptor, so we pop the single type
        popType(descriptor, 0);
    }
}

private int popType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
