GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        // Return an empty path if the tour set is empty
        return new GraphPathImpl<>(graph, null, null, Collections.emptyList(), 0.0);
    }

    // Start from an arbitrary vertex of the first edge
    E firstEdge = edgeList.get(0);
    V startVertex = graph.getEdgeSource(firstEdge);
    List<V> vertexList = new ArrayList<>();
    vertexList.add(startVertex);

    // Map to track visited edges
    Set<E> visitedEdges = new HashSet<>();
    visitedEdges.add(firstEdge);

    // Reconstruct the path
    V currentVertex = startVertex;
    while (vertexList.size() < edgeList.size() + 1) {
        E nextEdge = null;
        for (E edge : edgeList) {
            if (!visitedEdges.contains(edge)) {
                V source = graph.getEdgeSource(edge);
                V target = graph.getEdgeTarget(edge);
                if (source.equals(currentVertex) || target.equals(currentVertex)) {
                    nextEdge = edge;
                    visitedEdges.add(edge);
                    currentVertex = source.equals(currentVertex) ? target : source;
                    vertexList.add(currentVertex);
                    break;
                }
            }
        }
        if (nextEdge == null) {
            // If no next edge is found, the set does not form a single path
            throw new IllegalArgumentException("The provided set of edges does not form a single continuous path");
        }
    }

    // Calculate the total weight of the path
    double weight = 0.0;
    for (E edge : edgeList) {
        weight += graph.getEdgeWeight(edge);
    }

    return new GraphPathImpl<>(graph, startVertex, currentVertex, edgeList, weight);
}

