    if (from < 0 || to >= arr.length || from > to) {
        throw new IllegalArgumentException("Invalid range provided");
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

