private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertices must not be null");
    }

    int vertexCount = vertices.size();
    if (vertexCount <= 1) {
        return true; // A single vertex or empty set is trivially a clique
    }

    for (V vertex : vertices) {
        if (!graph.containsVertex(vertex)) {
            throw new IllegalArgumentException("Vertex set contains a vertex not in the graph");
        }

        Set<V> neighbors = new HashSet<>(graph.vertexSet());
        neighbors.retainAll(graph.neighborsOf(vertex));
        neighbors.add(vertex); // Include the vertex itself in its neighborhood for comparison

        if (neighbors.size() < vertexCount) {
            return false; // Not all vertices are connected to each other
        }
    }

    return true; // All vertices are fully connected
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> lowerBounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return lowerBounds;
    }

    Map<K, Integer> map = new TreeMap<>();
    for (int i = 0; i < keys.size(); i++) {
        map.put(keys.get(i), i);
    }

    Integer previousIndex = null;
    for (K key : map.keySet()) {
        Integer currentIndex = map.get(key);
        if (previousIndex == null) {
            lowerBounds.add(currentIndex);
        } else {
            lowerBounds.add(previousIndex);
        }
        previousIndex = currentIndex;
    }

    return lowerBounds;
}

