private int popType(final String descriptor, int index) {
    char c = descriptor.charAt(index);
    switch (c) {
        case 'B':
        case 'C':
        case 'D':
        case 'F':
        case 'I':
        case 'J':
        case 'S':
        case 'Z':
            // These are all single-word types
            // Pop one slot from the stack
            // (In real implementation, you would interact with the stack here)
            return index + 1;
        case '[':
            // These are arrays
            // Skip to the element type and pop one slot
            return popType(descriptor, index + 1);
        case 'L':
            // These are objects
            // Skip to the semicolon and pop one slot
            int semiColonIndex = descriptor.indexOf(';', index);
            return semiColonIndex + 1;
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
}

private List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> upperBounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return upperBounds; // Return empty list if input is null or empty
    }
    try {
        for (K key : keys) {
            if (key instanceof Comparable) {
                Comparable<K> comparableKey = (Comparable<K>) key;
                // Assuming the upper bound is the next integer value, adjust logic as needed
                int upperBound = comparableKey.compareTo((K) Integer.MAX_VALUE);
                upperBounds.add(upperBound);
            } else {
                throw new IllegalArgumentException("Keys must be comparable to compute upper bounds.");
            }
        }
    } catch (ClassCastException e) {
        throw new IllegalArgumentException("All keys must be of the same type that implements Comparable.");
    }
    return upperBounds;
}

