String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }

    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    // Use a list to facilitate modifications
    List<String> resultParts = new ArrayList<>(Arrays.asList(pathParts));

    for (String part : relativePathParts) {
        if (part.equals("..")) {
            // Move up one directory if possible
            if (resultParts.size() > 1) {
                resultParts.remove(resultParts.size() - 1);
            }
        } else if (!part.equals(".")) {
            // Add directory level
            resultParts.add(part);
        }
    }

    return String.join("/", resultParts);
}

